before:
Complete local Java example; the app itself does not execute it:
```java
import java.util.Properties;
import java.io.StringReader;
public class Main {

  public static void main(String[] args) throws java.io.IOException {
    Properties config = new Properties();
    config.load(new StringReader("minutes=15\n"));
    try {
      int minutes = Integer.parseInt(config.getProperty("minutes", "10"));
      if (minutes < 1 || minutes > 60) throw new IllegalArgumentException("range");
      System.out.println(minutes);
    } catch (IllegalArgumentException ex) {
      System.out.println("invalid configuration");
    }
  }
}
```

